// 同期 (ROADMAP 8, 2026-10-17): with the same 合言葉, the records of なまえ1〜4 (not names, not the guest) and their rests are kept alike on every device through the Worker in sync/. The Worker only keeps them; merging is C.merge here. Fetched and merged when someone is picked (before playing) and when the app comes back; sent a little after a change (SYNC_WAIT, at the latest SYNC_MAX_WAIT) and at once when a rest starts or ends or the app goes away. The screen is only changed when nothing is open on it. Failed calls are tried again after 30 seconds, 2 and 10 minutes, then wait for the next change; a wrong key, a record from a newer version or the 見張り番 stop it until おうちの方へ or the next pick. Off, or without a key, nothing is sent and the app plays from this device as before.
const SYNC_STORE='keisan-tetsudo-sync',SYNC_URL='https://keisan-tetsudo-sync.emisou.workers.dev',SYNC_WAIT=8000,SYNC_MAX_WAIT=30000,SYNC_PICK_WAIT=4000,SYNC_TIMEOUT=8000,SYNC_RETRY=[30000,120000,600000],SYNC_SLOTS=['p1','p2','p3','p4'];
const isPlain=o=>!!o&&typeof o==='object'&&!Array.isArray(o),canon=o=>JSON.stringify(o,(k,v)=>isPlain(v)?Object.fromEntries(Object.keys(v).sort().map(x=>[x,v[x]])):v);
let sync={version:1,on:false,key:'',url:'',last:{}},syncState=null,syncHalt=null,syncTimer=null,syncFirst=0,syncFails=0,syncBusy=null,syncAgain=null;
try{const v=JSON.parse(localStorage.getItem(SYNC_STORE));if(isPlain(v)&&v.version===1&&typeof v.on==='boolean'&&typeof v.key==='string'&&v.key.length<=64&&(v.url===undefined||typeof v.url==='string')&&(v.last===undefined||isPlain(v.last)))sync={...sync,...v,last:{...v.last}};}catch(e){}
function saveSync(){try{localStorage.setItem(SYNC_STORE,JSON.stringify(sync));return true;}catch(e){return false;}}
const syncURL=()=>(sync.url||SYNC_URL).replace(/\/+$/,'');
function syncReady(who){return sync.on&&sync.key.length>=12&&!!syncURL()&&SYNC_SLOTS.includes(who)&&!profilesBroken;}
async function syncCall(method,who,body){const ctl=new AbortController(),t=setTimeout(()=>ctl.abort(),SYNC_TIMEOUT);try{const r=await fetch(`${syncURL()}/v1/records/${who}`,{method,cache:'no-store',signal:ctl.signal,headers:{'x-sync-key':sync.key,...(body?{'content-type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});let data=null;try{data=await r.json();}catch(e){}return {status:r.status,data};}finally{clearTimeout(t);}}
function syncSoon(){if(!syncReady(store.who)||syncHalt||corrupt||conflict||syncFails)return;const now=Date.now();if(!syncFirst)syncFirst=now;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncNow(false),Math.max(0,Math.min(SYNC_WAIT,syncFirst+SYNC_MAX_WAIT-now)));}
// One sync at a time; a call while one runs comes once more after it.
function syncNow(apply){if(syncBusy){syncAgain={apply:apply||!!syncAgain?.apply};return syncBusy;}syncBusy=syncRun(apply).catch(e=>{console.error('sync',e);syncEnd('offline');}).finally(()=>{syncBusy=null;if(syncAgain){const a=syncAgain;syncAgain=null;syncNow(a.apply);}});return syncBusy;}
const syncTouch=()=>![...document.querySelectorAll('dialog[open]')].some(d=>d.id!=='who'&&d.id!=='parents');
function syncEnd(why){const who=store.who;if(why==='ok'){syncFails=0;sync.last[who]=Date.now();saveSync();}else if(why==='offline'){syncFails++;clearTimeout(syncTimer);syncTimer=syncFails<=SYNC_RETRY.length?setTimeout(()=>syncNow(false),SYNC_RETRY[syncFails-1]):null;}else syncHalt=why;syncState={who,why};renderSync();}
async function syncRun(apply){const who=store.who;if(!syncReady(who)||syncHalt||corrupt||conflict)return;clearTimeout(syncTimer);syncTimer=null;syncFirst=0;syncState={who,why:'busy'};renderSync();
let last=0;for(let tries=0;tries<3;tries++){let got;try{got=await syncCall('GET',who);}catch(e){return syncEnd('offline');}if(store.who!==who)return;if(got.status===401)return syncEnd('key');if(got.status!==200||!isPlain(got.data)||!Number.isSafeInteger(got.data.rev))return syncEnd(got.status===503?'server':'offline');
const cloud=got.data.data;let record=state,r=rest;if(cloud){if(!isPlain(cloud)||!C.valid(cloud.record)||cloud.record.version!==3)return syncEnd('update');if(lastSaved===null||!C.total(state)&&!state.edges.length&&!state.kindsAt&&!state.life){record=JSON.parse(JSON.stringify(cloud.record));C.upgradeCards(record);}else record=C.merge(state,cloud.record,profiles.device);if(!record)return syncEnd('update');const c=cloud.rest;if(C.validRest(c))r=C.mergeRest(restNew?{...rest,on:c.on,play:c.play,rest:c.rest,...(c.setAt?{setAt:c.setAt}:{})}:rest,c,REST_UNIT)||rest;}restNew=false;
if(canon(r)!==canon(rest)){rest=r;saveRest();renderRestNote();}if(canon(record)!==canon(state)&&apply&&syncTouch()&&!corrupt&&!conflict){try{if(store.read()!==lastSaved){conflict=true;save();syncState=null;renderSync();return;}state=record;lastSaved=store.write(state);}catch(e){storageOK=false;}entry='';selected=state.current;render();if($('parents').open)renderPeople();if(!$('who').open&&!$('parents').open){centerMap();showReward();if(!showRest())showNews();}}
if(cloud&&canon(cloud.record)===canon(record)&&canon(cloud.rest)===canon(rest))return syncEnd('ok');if(cloud&&C.shrinks(cloud.record,record))return syncEnd('guard');
let put;try{put=await syncCall('PUT',who,{rev:got.data.rev,data:{record,rest}});}catch(e){return syncEnd('offline');}if(store.who!==who)return;if(put.status===200)return syncEnd('ok');if(put.status===401)return syncEnd('key');if(put.status===400||put.status===413)return syncEnd('server');if(put.status!==409&&put.status!==422)return syncEnd(put.status===503?'server':'offline');last=put.status;}
syncEnd(last===422?'guard':'offline');}
const SYNC_NOTES={busy:'そろえています…',ok:'同期済み',offline:'この端末だけに保存中です（通信できません）。つながったら そろえます。',key:'合言葉が ちがいます。入れ直してください。',update:'ほかの端末の記録が 新しい版です。下の「アプリを最新に更新」をしてください。',guard:'記録が減りそうなため、同期を止めました。この端末の記録は そのままです。',server:'サーバーで うまく保存できませんでした。'};
function renderSync(){const who=store.who,at=sync.last[who],hm=t=>{const d=new Date(t);return `${d.getMonth()+1}/${d.getDate()} ${d.getHours()}:${String(d.getMinutes()).padStart(2,'0')}`;};$('sync-on').checked=sync.on;$('sync-key').placeholder=sync.key?'保存ずみ（変えるときだけ入力）':'12文字以上';$('sync-now').disabled=!syncReady(who);
$('sync-status').textContent=!syncURL()?'同期の準備中です（まだ サーバーが ありません）。':!sync.key?'合言葉を入れると 同期できます。':!sync.on?'同期は オフです。この端末だけに保存しています。':!SYNC_SLOTS.includes(who)?'ゲストは 同期しません。':profilesBroken?'なまえの記録が読み込めないため、同期できません。':syncState?.who===who?SYNC_NOTES[syncState.why]+(syncState.why==='ok'&&at?`（${hm(at)}）`:''):at?`さいごに そろえた時刻：${hm(at)}`:'まだ そろえていません。';}
$('sync-save').onclick=()=>{const k=$('sync-key').value.trim();if(k&&(k.length<12||k.length>64)){$('sync-status').textContent='合言葉は 12〜64文字です。';return;}if(k)sync.key=k;sync.on=$('sync-on').checked;$('sync-key').value='';syncHalt=null;syncFails=0;syncState=null;if(!saveSync()){$('sync-status').textContent='設定を保存できませんでした。';return;}renderSync();if(syncReady(store.who))syncNow(true);};
$('sync-on').onchange=()=>$('sync-save').click();$('sync-now').onclick=()=>{syncHalt=null;syncFails=0;syncNow(true);};
document.addEventListener('visibilitychange',()=>{if(document.hidden)syncNow(false);else if(!syncHalt)syncNow(true);});window.addEventListener('online',()=>{syncFails=0;syncNow(false);});
// Newly turned-on kinds get a celebration once, then the first new button is chosen. Not on closing おうちの方へ (the grown-up would be the one to see it), but when the child picks who plays or starts on a problem.
function showNews(){if(!store.who||!state.news?.length||state.pending||document.querySelector('dialog[open]'))return false;$('news-list').innerHTML=state.news.map(k=>`<li><b>${OP_LABELS[C.KINDS[k]][0]}</b>${esc(KIND_NAMES[k])}</li>`).join('');$('news').showModal();window.RailDrive?.seikai();return true;}
function closeNews(){const first=state.news?.[0];C.seeNews(state);if(first)C.setMode(state,C.KINDS[first]);entry='';$('news').close();render();lookCall();}
$('news-close').onclick=closeNews;$('news').addEventListener('cancel',e=>{e.preventDefault();closeNews();});
$('app-version').textContent=document.querySelector('meta[name="app-version"]')?.content||'不明';
$('update-app').onclick=async()=>{
const button=$('update-app');button.disabled=true;$('update-status').textContent='最新版を確認しています…';
try{
const url=new URL('index.html',document.baseURI);url.searchParams.set('update',Date.now().toString());
const response=await fetch(url.href,{cache:'no-store'});
if(!response.ok)throw Error('通信エラー '+response.status);
const html=await response.text();
const version=new DOMParser().parseFromString(html,'text/html').querySelector('meta[name="app-version"]')?.content;
if(!version)throw Error('更新データを確認できませんでした');
$('update-status').textContent='最新版を開きます。記録はそのまま残ります。';
location.replace(url.href);
}catch(error){button.disabled=false;$('update-status').textContent='更新できませんでした：'+error.message+'。通信を確認して、もう一度お試しください。';}
};
let resetAnswer=null;
function resetQuiz(){const a=12+Math.floor(Math.random()*8),b=3+Math.floor(Math.random()*7);resetAnswer=a*b;$('reset-question').textContent=`${a} × ${b} =`;$('reset-answer').value='';let undo=false;try{undo=!!store.beforeReset();}catch(e){}$('reset-undo').hidden=!undo;$('reset-app').disabled=$('reset-undo').disabled=conflict;}
$('reset-app').onclick=()=>{if(conflict)return;if(Number($('reset-answer').value)!==resetAnswer||!/^\d+$/.test($('reset-answer').value.trim())){$('reset-status').textContent='確認の答えがちがいます。';resetQuiz();return;}if(!confirm(`${profiles.names[store.who]}の 正解数・開通した駅・車両カードを消して、玖波駅から最初にもどします。よろしいですか？`)){resetQuiz();return;}if(!restart()){$('reset-status').textContent='リセット前の記録を残せないため、リセットを中止しました。先にバックアップを保存してください。';return;}resetQuiz();$('reset-status').textContent='最初からに もどしました。';};
$('reset-undo').onclick=()=>{if(conflict)return;try{const data=store.beforeReset();if(!data)throw Error();C.upgradeCards(data);if(!confirm('リセット・復元の前の記録に戻しますか？ そのあとに進めた分は消えます。'))return;state=data;C.revive(state,Date.now());corrupt=false;entry='';selected=state.current;render();if(!conflict&&storageOK)store.dropBeforeReset();centerMap();$('parents').close();showReward();}catch(e){$('reset-status').textContent='リセット前の記録を読み込めませんでした。';}};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=store.backupName;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('ファイルが大きすぎます。');let data=JSON.parse(await f.text());if(data?.version===1)data=C.migrate(data);if(data?.version===2){data=C.fromV2(data,profiles.device);if(data){C.setKinds(data,state.kinds);C.setLook(data,!!state.lookButton,state.lookStay||LOOK_STAY);C.setThree(data,state.threeWay||'');data.news=[];}}if(!C.valid(data)||data.version!==3)throw Error('有効なバックアップではありません。');C.upgradeCards(data);if(!confirm(`${profiles.names[store.who]}の記録を、このバックアップの記録に置き換えますか？${syncReady(store.who)?' 同期している ほかの端末も、この記録に そろいます。':''}`))return;if(!corrupt){try{store.keepBeforeReset(JSON.stringify(state));}catch(e){throw Error('いまの記録を残せないため、中止しました。');}}C.newLife(data,Date.now());state=data;corrupt=false;conflict=false;lastSaved=store.read();entry='';selected=state.current;render();centerMap();$('parents').close();showReward();}catch(err){$('import-status').textContent='復元できませんでした。'+err.message;}finally{e.target.value='';}};
$('zoom-in').onclick=()=>zoom(.7);$('zoom-out').onclick=()=>zoom(1/.7);$('map-current').onclick=()=>centerMap();$('map-all').onclick=mapAll;
let normalCamera=null;
$('map-full').onclick=()=>{const world=document.querySelector('.world'),on=!world.classList.contains('map-expanded');if(on)normalCamera={...camera};world.classList.toggle('map-expanded',on);$('map-full').textContent=on?'もどす':'大きく見る';if(on)mapAll();else{camera={...normalCamera};normalCamera=null;camera.height=camera.width/mapAspect();updateCamera();}};
const pointers=new Map();let gesture=null,moved=false;
$('map').addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});$('map').setPointerCapture(e.pointerId);moved=false;gesture={x:e.clientX,y:e.clientY,camera:{...camera},distance:pointers.size===2?Math.hypot(...(()=>{const p=[...pointers.values()];return[p[0].x-p[1].x,p[0].y-p[1].y];})()):null};if(pointers.size===2){const p=[...pointers.values()];gesture.mx=(p[0].x+p[1].x)/2;gesture.my=(p[0].y+p[1].y)/2;}});
$('map').addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!gesture)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);if(gesture.distance){const r=$('map').getBoundingClientRect(),mx=(p[0].x+p[1].x)/2,my=(p[0].y+p[1].y)/2;camera.x-=(mx-gesture.mx)*camera.width/r.width;camera.y-=(my-gesture.my)*camera.height/r.height;zoom(gesture.distance/d,(mx-r.left)/r.width,(my-r.top)/r.height);gesture.distance=d;gesture.mx=mx;gesture.my=my;moved=true;}return;}const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(Math.abs(dx)+Math.abs(dy)>5)moved=true;camera.x=gesture.camera.x-dx*camera.width/$('map').clientWidth;camera.y=gesture.camera.y-dy*camera.height/$('map').clientHeight;updateCamera();});
$('map').addEventListener('pointerup',e=>{if(!moved){const node=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-station],[data-name]');if(node){const id=node.dataset.station||node.dataset.name,st=R.stations[id];showSelection(id);window.RailDrive?.say(st.say||st.reading);}}pointers.delete(e.pointerId);gesture=null;});$('map').addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);gesture=null;});$('map').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.station){e.preventDefault();showSelection(e.target.dataset.station);}});
$('map').addEventListener('wheel',e=>{if(e.ctrlKey){e.preventDefault();zoom(e.deltaY>0?1.08:.92);}},{passive:false});
// A resize keeps the view, also on the large map: on iPhone the address bar coming and going resized it and sent the large map back to the whole (2026-10-15).
function resizeMap(){const cy=camera.y+camera.height/2;camera.height=camera.width/mapAspect();camera.y=cy-camera.height/2;updateCamera();}
window.addEventListener('resize',resizeMap);
if(window.visualViewport)window.visualViewport.addEventListener('resize',resizeMap);
new ResizeObserver(resizeMap).observe($('map-wrap'));
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]')||e.target.closest('#map,button,input,a'))return;if(e.key==='Enter'&&state.solved){e.preventDefault();$('next').click();}else if(/^\d$/.test(e.key)){e.preventDefault();key(e.key);}else if(e.key==='Backspace'){e.preventDefault();key('clear');}else if(e.key==='Enter'){e.preventDefault();key('submit');}});
$('legend').innerHTML=R.lines.map(l=>`<span><i style="--line:${l.fill||l.color}${l.casing?`;box-shadow:0 0 0 1.5px ${l.casing}`:''}"></i>${l.name}</span>`).join('');centerMap();render();openWho();
